                return 0
            visited[i] = 1
            tot = 1
            for k in adjacencyList[i]:
                tot += dfs(k, visited)
            if tot % seats == 0:
                res[0] += tot // seats
            else:
                res[0] += tot // seats + 1
            return tot

        for i in adjacencyList[0]:
            total = dfs(i, visited)
        return res[0]
