import random

class Node:
    __slots__ = ('val', 'cnt', 'size', 'priority', 'left', 'right')
    def __init__(self, val):
        self.val = val
        self.cnt = 1
        self.size = 1
        self.priority = random.random()
        self.left = None
        self.right = None

def size(t):
    return t.size if t else 0

def update(t):
    if t:
        t.size = t.cnt + size(t.left) + size(t.right)

def rotate_right(t):
    l = t.left
    t.left = l.right
    l.right = t
    update(t)
    update(l)
    return l

def rotate_left(t):
    r = t.right
    t.right = r.left
    r.left = t
    update(t)
    update(r)
    return r

def insert(t, val):
    if t is None:
        return Node(val)
    if val == t.val:
        t.cnt += 1
    elif val < t.val:
        t.left = insert(t.left, val)
        if t.left.priority > t.priority:
            t = rotate_right(t)
    else:
        t.right = insert(t.right, val)
        if t.right.priority > t.priority:
            t = rotate_left(t)
    update(t)
    return t

def remove(t, val):
    if t is None:
        return None
    if val == t.val:
        if t.cnt > 1:
            t.cnt -= 1
            update(t)
            return t
        if t.left is None:
            return t.right
        if t.right is None:
            return t.left
        if t.left.priority > t.right.priority:
            t = rotate_right(t)
            t.right = remove(t.right, val)
        else:
            t = rotate_left(t)
            t.left = remove(t.left, val)
    elif val < t.val:
        t.left = remove(t.left, val)
    else:
        t.right = remove(t.right, val)
    update(t)
    return t

def get(t, k):
    # k-th smallest (1-indexed)
    while t:
        left_size = size(t.left)
        if k <= left_size:
            t = t.left
        elif k <= left_size + t.cnt:
            return t.val
        else:
            k -= left_size + t.cnt
            t = t.right
    return None
```

